/* Additional regional vector scenery, keeping the existing eight scenes. */
const baseRegionScene=regionScene;
regionScene=function(id){
 if(id<=8)return baseRegionScene(id);
 const land='<path d="M0 430H1000V700H0Z" fill="#a2b59f"/><path d="M0 700 470 430h60l470 270" fill="#c7bca0"/>';
 const trees=sceneTree(90,480,1)+sceneTree(900,500,1.1);
 const building=(label,color='#c7c6b4')=>`<path d="M180 460V210h640v250Z" fill="${color}"/><path d="M160 200h680v25H160Z" fill="#647f8c"/>${sceneWindows(210,250,14,4,42,38,'#96bec9')}<path d="M450 460V350h100v110" fill="#597783"/><rect x="370" y="205" width="260" height="43" rx="3" fill="#546f7d"/><text x="500" y="235" text-anchor="middle" font-family="sans-serif" font-size="23" fill="#edf0d5">${label}</text>`;
 let scene=land+trees;
 if(id===9)scene=land+sceneHouse(-60,520,280,300,'#a7afa2')+sceneHouse(750,530,290,330,'#9baca7')+sceneHouse(290,445,145,180,'#bbc0a5')+sceneHouse(545,445,145,170,'#bfae92')+'<path d="M210 240q300 100 550 10" fill="none" stroke="#657d7d" stroke-width="4"/>'+sceneLantern(250,335);
 if(id===10)scene=land+building('마을회관')+trees+'<path d="M100 560h220v50H100m580-50h220v50H680" fill="#768c7f"/>';
 if(id===11)scene=land+building('119 · 소방서','#b99c8c')+'<path d="M230 460V325h155v135m230 0V325h155v135" fill="#62818a"/><path d="M250 450v-75h115v75m270 0v-75h115v75" fill="#b86e59"/><path d="M270 360h75m310 0h75" stroke="#e4dcb5" stroke-width="8"/>'+trees;
 if(id===12)scene='<path d="M0 470 270 130l220 280L690 100l310 360v240H0Z" fill="#7e9e94"/><path d="M0 530 340 245l190 280 280-245 190 275v145H0Z" fill="#668d79"/><path d="m450 700 160-145-170-65 100-140-20-50-90 180 130 90L240 700Z" fill="#d0c29e"/>'+sceneTree(40,650,1.5)+sceneTree(930,620,1.8);
 if(id===13)scene=land+trees+Array.from({length:12},(_,i)=>{const x=120+(i%6)*145,y=440+Math.floor(i/6)*150;return `<path d="M${x} ${y}v-50q25-40 50 0v50Z" fill="#8e9d96" stroke="#d2d3ba" stroke-width="3"/><path d="M${x+25} ${y-48}v30m-10-20h20" stroke="#617c79" stroke-width="4"/>`;}).join('');
 if(id===14)scene='<path d="M0 280 180 180l200 120 220-140 400 180v360H0Z" fill="#7d9d87"/><path d="M140 580V330a360 280 0 0 1 720 0v250Z" fill="#9ba99d"/><path d="M235 580V340a265 210 0 0 1 530 0v240Z" fill="#3e6171"/><path d="M285 580V355a215 180 0 0 1 430 0v225Z" fill="#34525f"/><path d="M0 700 455 470h90l455 230Z" fill="#788f91"/><path d="M500 500v200" stroke="#e8d5a2" stroke-width="6" stroke-dasharray="30 25"/><path d="M310 390h45m290 0h45" stroke="#f0d19d" stroke-width="10"/>';
 if(id===15)scene=land+trees+'<path d="M230 480V300h540v180Z" fill="#c6b598"/><path d="m160 310 340-170 340 170-110-20H270Z" fill="#617d80"/><path d="M205 310h590M295 480V315m410 165V315" fill="none" stroke="#866e5f" stroke-width="16"/><path d="M385 480V330h230v150" fill="#879482"/><path d="m385 340 230 130m-230 0 230-130" stroke="#bcb79b" stroke-width="7"/><path d="M130 530h740v20H130m40 30h660v20H170" fill="#a8ac9b"/>';
 if(id===16)scene='<path d="M0 350H1000V700H0Z" fill="#7eb7c3"/><path d="M0 580 270 450l300 40 430 210H0Z" fill="#829d8d"/><path d="m380 490 35-310h130l35 310Z" fill="#e1d4b7"/><path d="M402 280h150v45H402m5-100h145v35H407" fill="#ac8370"/><path d="M398 180v-60h165v60Z" fill="#658c99"/><path d="m380 120 100-70 100 70Z" fill="#607c88"/><path d="M480 130 760 70v190Z" fill="#eee2ab" opacity=".35"/><path d="M480 490V390h40v100" fill="#5d7b83"/><path d="M650 420h230m-130 100h220m-840 70h180" stroke="#c2d9ca" stroke-width="4"/>';
 if(id===17)scene=land+trees+'<path d="M90 535h820v165H90Z" fill="#7e9f7d"/>'+[230,500,770].map(x=>`<path d="M${x} 500v100m-40 0 40-100 40 100" fill="none" stroke="#8a8067" stroke-width="9"/><circle cx="${x}" cy="435" r="67" fill="#e4dbbd"/><circle cx="${x}" cy="435" r="48" fill="#688b9d"/><circle cx="${x}" cy="435" r="31" fill="#bd8272"/><circle cx="${x}" cy="435" r="15" fill="#e0c571"/>`).join('');
 if(id===18)scene=land+building('병원 · HOSPITAL','#cbd4c5')+trees+'<path d="M480 125h40v90h-40m-25-65h90v40h-90" fill="#b87973"/><path d="M650 570v-65h180v65Z" fill="#e3d9bb"/><path d="M700 515h20v40h-20m-10-30h40v20h-40" fill="#b87973"/>';
 if(id===19)scene='<path d="M0 330H1000V700H0Z" fill="#78b9c5"/><path d="M0 500q270-100 500 40t500-15v175H0Z" fill="#ddd0a7"/><path d="M0 470q270-100 500 40t500-15" fill="none" stroke="#e0e4c7" stroke-width="13"/><path d="M0 380h1000m-800 65h180m230-50h230" stroke="#bcded8" stroke-width="3"/><path d="M170 645V480m-85 0q85-150 170 0Z" fill="#ba9c7d" stroke="#8e8a73" stroke-width="6"/><path d="M730 620h180l-50 25H700Z" fill="#9b8773"/>';
 if(id===20)scene=land+trees+'<ellipse cx="500" cy="580" rx="150" ry="60" fill="#829787"/><path d="M350 570v-95q150 60 300 0v95q-150 80-300 0Z" fill="#a8ad97" stroke="#788d83" stroke-width="5"/><ellipse cx="500" cy="475" rx="150" ry="47" fill="#4f7c88" stroke="#c7c5a7" stroke-width="15"/><path d="M370 485V280m260 205V280" stroke="#8f8870" stroke-width="18"/><path d="m310 285 190-120 190 120Z" fill="#657f7d"/><path d="M500 285v190" stroke="#c4b79a" stroke-width="6"/><path d="M470 465v40h60v-40" fill="#8b9f99"/>';
 if(id===21)scene=land+[[-80,550,250,230],[170,485,190,210],[410,440,160,165],[610,490,200,240],[840,550,240,280]].map(([x,y,w,h],i)=>sceneHouse(x,y,w,h,['#9aa79a','#b7a58d','#8ea8a2'][i%3])).join('')+'<path d="M0 580h340m300 0h360" stroke="#728b81" stroke-width="14"/><path d="M70 610h100v70H70m690-40h100v60H760" fill="#6c8e8b"/>';
 if(id===22)scene=land+building('RESEARCH · 출입 통제','#a8bac1')+'<path d="M60 550h880M100 440v200m100-200v200m100-200v200m100-200v200m100-200v200m100-200v200m100-200v200m100-200v200m100-200v200" stroke="#587786" stroke-width="9"/><path d="M390 570h220v70H390Z" fill="#b48270"/><text x="500" y="614" text-anchor="middle" fill="#fff1cf" font-size="22">출입 금지</text>';
 return `<svg class="forest region-scene" data-scene="${id}" viewBox="0 0 1000 700" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="extra-sky" x2="0" y2="1"><stop stop-color="#9cc1cb"/><stop offset="1" stop-color="#e0d5b2"/></linearGradient></defs><rect width="1000" height="700" fill="url(#extra-sky)"/><circle cx="750" cy="135" r="50" fill="#f3e3b7" opacity=".6"/><ellipse cx="200" cy="150" rx="145" ry="20" fill="#edf1db" opacity=".3"/>${scene}</svg>`;
};
